bool ServiceAccountManager::FindRecord(ODRecordType type, ODAttributeType attribute,
                                      const char* value, ODRecordRef& record) {
    _errmsg = "Failed to query the local account directory.";
    if(record != NULL) {
        CFRelease(record);
        record = NULL;
    }

    CFStringRef text = CFStringCreateWithCString(NULL, value, kCFStringEncodingUTF8);
    ODQueryRef query = ODQueryCreateWithNode(NULL, _node, type, attribute, kODMatchEqualTo,
                                           text, kODAttributeTypeGUID, 1, NULL);
    CFRelease(text);

    if(query == NULL) {
        return false;
    }

    CFErrorRef error = NULL;
    CFArrayRef results = ODQueryCopyResults(query, false, &error);
    CFRelease(query);

    
    bool success = results != NULL && error == NULL;
    
    if(success && CFArrayGetCount(results) != 0) {
        record = (ODRecordRef)CFRetain(CFArrayGetValueAtIndex(results, 0));
    }

    if(results != NULL) {
        CFRelease(results);
    }

    if(error != NULL) {
        CFRelease(error);
    }

    return success;
}

bool ServiceAccountManager::SaveState(bool pending) {
    _errmsg = "Failed to save the account state.";

    // 디렉터리 잠금을 보유하므로 이전 실행의 임시 파일을 지우고 같은 이름을 사용한다.
    if(unlinkat(_directory, "service-account.tmp", 0) != 0 && errno != ENOENT) {
        return false;
    }

    int fd = openat(_directory, "service-account.tmp",
                    O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC, 0600);
    if(fd == -1) {
        return false;
    }

    char state[256];
    int length = snprintf(state, sizeof(state), "%s %s %s %s %s\n",
                          _name, _id, _uuid[0], _uuid[1], pending ? "pending" : "ready");
    bool success = write(fd, state, length) == length && fsync(fd) == 0;

    if(close(fd) != 0) {
        success = false;
    }

    // 쓰기와 동기화가 끝난 임시 파일로 교체하여 기존 기록이 일부만 덮이는 것을 방지한다.
    if(success) {
        success = renameat(_directory, "service-account.tmp", _directory, "service-account") == 0;
    }

    if(!success) {
        unlinkat(_directory, "service-account.tmp", 0);
    }

    if(success) {
        _hasState = true;
        _pending = pending;
    }

    return success;
}

